async function focusedScene(page){return page.evaluate(()=>{const item=window.__qaGL.find(r=>!r.disposed&&r.scene&&r.canvas.isConnected),d=item.scene.userData,kind=d.focusKind,id=d.focusId,key={fish:'fishInstanceId',plant:'plantId',habitat:'habitatId'}[kind];let target=null;item.scene.updateMatrixWorld(true);if(key)item.scene.traverse(node=>{if(!target&&node.isGroup&&node.userData[key]===id)target=node;});const result={kind:kind||null,id:id||null,camera:item.camera.position.toArray(),center:[d.focusCenterX,d.focusCenterY,d.focusCenterZ]};if(target){const b=new THREE.Box3();target.traverse(node=>{if(node.isMesh&&!node.userData.ignorePick&&node.visible)b.union(new THREE.Box3().setFromObject(node));});if(!b.isEmpty()){const r=item.canvas.getBoundingClientRect(),pts=[];for(const x of[b.min.x,b.max.x])for(const y of[b.min.y,b.max.y])for(const z of[b.min.z,b.max.z])pts.push(new THREE.Vector3(x,y,z).project(item.camera));result.targetCenter=b.getCenter(new THREE.Vector3()).toArray();result.projectedCenter=b.getCenter(new THREE.Vector3()).project(item.camera).toArray();result.maxX=Math.max(...pts.map(p=>Math.abs(p.x)));result.maxY=Math.max(...pts.map(p=>Math.abs(p.y)));result.pixelWidth=(Math.max(...pts.map(p=>p.x))-Math.min(...pts.map(p=>p.x)))*r.width/2;result.pixelHeight=(Math.max(...pts.map(p=>p.y))-Math.min(...pts.map(p=>p.y)))*r.height/2;result.worldScale=target.getWorldScale(new THREE.Vector3()).toArray();}}return result;});}
