async function residentBounds(page){return page.evaluate(()=>{const item=window.__qaGL.find(r=>!r.disposed&&r.scene&&r.canvas.isConnected),result=[];item.scene.updateMatrixWorld(true);item.scene.traverse(group=>{if(group.type==='Group'&&group.userData.fishInstanceId&&group.parent?.userData.fishInstanceId!==group.userData.fishInstanceId){const bounds=new THREE.Box3();group.traverse(mesh=>{if(mesh.isMesh&&!mesh.userData.ignorePick)bounds.union(new THREE.Box3().setFromObject(mesh));});result.push({id:group.userData.fishInstanceId,min:bounds.min.toArray(),max:bounds.max.toArray()});}});return result;});}
function assertBounds(residents){for(const resident of residents)assert(resident.min[0]>=-6.001&&resident.max[0]<=6.001&&resident.min[1]>=-.001&&resident.max[1]<=5.201&&resident.min[2]>=-3.301&&resident.max[2]<=3.301,'Resident geometry leaves inner vessel: '+JSON.stringify(resident));}
async function checkPick(page,key,id){await canvas(page).scrollIntoViewIfNeeded();const candidates=await page.evaluate(({key,id})=>{
 const r=window.__qaGL.find(r=>!r.disposed&&r.scene&&r.canvas.isConnected);const box=r.canvas.getBoundingClientRect();const points=[];
 r.scene.traverse(node=>{if(node.isMesh&&node.userData[key]===id){const center=new THREE.Box3().setFromObject(node).getCenter(new THREE.Vector3()).project(r.camera);if(center.z<1&&Math.abs(center.x)<.98&&Math.abs(center.y)<.98)points.push({x:box.x+(center.x+1)*box.width/2,y:box.y+(1-center.y)*box.height/2});}});return points;
 },{key,id});
 for(const point of candidates.slice(0,16)){await page.mouse.click(point.x,point.y);await page.waitForTimeout(80);const current=await state(page);if(key==='habitatId'?current.selectedHabitatItemId===id:current.ecosystemFocusId===id)return true;}return false;
}
